  function renderHistory(){historyWrap.hidden=!guesses.length;updateSharedGuessMenu();history.dataset.guessCount=String(guesses.length);history.className=`guess-history history-${sharedGuessView}-view`;if(sharedGuessView==="board"){const item=document.createElement("li"),actionList=document.createElement("div"),grid=document.createElement("div");item.className="history-board-view";actionList.className="board-view-actions";grid.className="history-board-grid";guesses.forEach((guess,index)=>{const row=document.createElement("div"),word=document.createElement("strong");row.className="board-view-action-row";row.classList.toggle("is-editing",index===editingIndex);word.textContent=guess.word.toUpperCase();row.append(word,historyActions(guess,index));actionList.append(row)});boardIndices.forEach(board=>{const panel=document.createElement("section"),heading=document.createElement("h3"),rows=document.createElement("div");panel.className="history-board-panel";panel.dataset.boardIndex=String(board);heading.textContent=`Board ${board+1}`;rows.className="history-board-rows";guesses.forEach((guess,index)=>rows.append(historyBoard(guess,index,board)));panel.append(heading,rows);grid.append(panel)});item.append(actionList,grid);history.replaceChildren(item)}else history.replaceChildren(...guesses.map((guess,index)=>{const li=document.createElement("li"),word=document.createElement("span"),boards=document.createElement("span");word.className="history-word";word.textContent=guess.word.toUpperCase();boards.className="history-boards";guess.feedback.forEach((_,board)=>boards.append(historyBoard(guess,index,board)));li.classList.toggle("is-editing",index===editingIndex);li.append(word,boards,historyActions(guess,index));return li}));syncCompletedHistory();syncHistoryBoardHighlight();syncNoMatchBoards()}
